                session_id,
                "unsupported_media",
                collected,
                "Recebi uma mídia que este canal não transcreve com segurança. Vou encaminhar para um atendente.",
            )

        decision = self._decide(sanitized, content, state, collected)
        if decision.intent is Intent.HUMAN:
            return self._handoff(
                session_id,
                "human_requested",
                collected,
                "Claro. Vou encaminhar a conversa para um atendente humano.",
