                event="quote_succeeded",
            )
            return self._reply(session_id, _format_quote(result.payload))
        except QuoteRejected as exc:
            self.repository.add_quote_attempts(session_id, exc.quote_id, exc.attempts)
            return self._handoff(
                session_id,
                "eligibility_rejected",
                collected,
                f"A cotação automática foi recusada: {exc.reason} Vou encaminhar para análise humana.",
            )
        except QuoteInvalid as exc:
            self.repository.add_quote_attempts(session_id, exc.quote_id, exc.attempts)
            return self._handoff(
                session_id,
                "invalid_quote_payload",
                collected,
                "O serviço rejeitou os dados da cotação. Vou encaminhar para revisão humana.",
            )
        except QuoteUnavailable as exc:
            self.repository.add_quote_attempts(session_id, exc.quote_id, exc.attempts)
            return self._handoff(
                session_id,
                "quote_service_unavailable",
                collected,
                "O serviço de cotação está temporariamente indisponível. Não vou estimar um preço; um atendente continuará o atendimento.",
            )

    def _complete(self, session_id: str) -> TurnResult:
        self.repository.update_session(
