import uuid

from fastapi import FastAPI, Request
from fastapi.responses import JSONResponse
from pydantic import BaseModel, Field
from starlette.middleware.base import RequestResponseEndpoint
from starlette.responses import Response

from .config import Settings, get_settings
from .logging_config import configure_logging
from .providers import LLMProvider, provider_from_settings
from .quote_client import QuoteClient
from .repository import Repository, create_db_engine
from .service import AgentService, TurnResult


class MessageInput(BaseModel):
    content: str = Field(min_length=1, max_length=4000)
    message_type: str = Field(default="text", pattern=r"^(text|image|audio|document)$")


def create_app(
    *,
    settings: Settings | None = None,
    repository: Repository | None = None,
    provider: LLMProvider | None = None,
    quote_client: QuoteClient | None = None,
) -> FastAPI:
    cfg = settings or get_settings()
    configure_logging(cfg.log_level)
    repo = repository or Repository(create_db_engine(cfg.database_url))
    if cfg.auto_create_schema:
        repo.create_schema()
    llm = provider or provider_from_settings(cfg)
    quotes = quote_client or QuoteClient(
        cfg.quote_service_url,
        timeout_seconds=cfg.quote_timeout_seconds,
        max_attempts=cfg.quote_max_attempts,
        backoff_seconds=cfg.quote_backoff_seconds,
    )
    service = AgentService(repo, llm, quotes)

    app = FastAPI(title="AutoSeguro Agent API", version="1.0.0")
    app.state.repository = repo
    app.state.quote_client = quotes
    app.state.service = service

    @app.middleware("http")
    async def correlation_id(request: Request, call_next: RequestResponseEndpoint) -> Response:
        request_id = request.headers.get("x-correlation-id", str(uuid.uuid4()))
        response = await call_next(request)
        response.headers["x-correlation-id"] = request_id
        return response

    @app.exception_handler(KeyError)
    async def not_found(_: Request, exc: KeyError) -> JSONResponse:
        return JSONResponse(
            status_code=404, content={"detail": f"Sessão não encontrada: {exc.args[0]}"}
        )

    @app.exception_handler(ValueError)
    async def conflict(_: Request, exc: ValueError) -> JSONResponse:
        return JSONResponse(status_code=409, content={"detail": str(exc)})

    @app.get("/health")
    def health() -> dict[str, object]:
        database_ok = repo.ping()
        quote_ok = quotes.health()
        return {
            "status": "ok" if database_ok else "degraded",
            "database": "ok" if database_ok else "unavailable",
            "quote_service": "ok" if quote_ok else "unavailable",
        }

    @app.post("/v1/sessions", response_model=TurnResult, status_code=201)
    def create_session() -> TurnResult:
        return service.create_session()

    @app.post("/v1/sessions/{session_id}/messages", response_model=TurnResult)
    def send_message(session_id: str, body: MessageInput) -> TurnResult:
        return service.handle_message(session_id, body.content, body.message_type)

    @app.get("/v1/sessions/{session_id}")
    def get_session(session_id: str):  # type: ignore[no-untyped-def]
        return service.get_session(session_id)

    @app.get("/v1/sessions/{session_id}/trace")
    def get_trace(session_id: str) -> dict[str, object]:
        return service.trace(session_id)

    return app


def _build_default_app() -> FastAPI:
    try:
        return create_app()
    except ValueError as exc:
        error_detail = str(exc)
        app = FastAPI(title="AutoSeguro Agent API", version="1.0.0")

        @app.get("/health", status_code=503)
        def configuration_error() -> dict[str, str]:
            return {"status": "configuration_error", "detail": error_detail}

        return app


app = _build_default_app()
