    pass


class QuoteClient:
    RETRYABLE = {500, 502, 503}

    def __init__(
        self,
        base_url: str,
        *,
        timeout_seconds: float = 3.0,
        max_attempts: int = 3,
        backoff_seconds: float = 0.25,
