#!/usr/bin/env python3
"""Export the visible Codex conversation without secrets or internal reasoning."""

from __future__ import annotations

import argparse
import hashlib
import json
import re
from pathlib import Path
from typing import Any

HOME_PATH = re.compile(r"$WORKSPACE_HOME")
PERSON_NAME = re.compile(r"\bHugo(?:\s+Parr[^\s/\"']+)?", re.IGNORECASE)
EMAIL = re.compile(r"\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b", re.IGNORECASE)
CPF = re.compile(r"\b\d{3}\.\d{3}\.\d{3}-\d{2}\b")
PHONE = re.compile(r"(?<!\d)(?:\+?55\s*)?(?:\(?\d{2}\)?\s*)?9?\d{4}[-\s]?\d{4}(?!\d)")
PRIVATE_KEY = [MASK](
    r"-----BEGIN (?:RSA |EC |OPENSSH )?PRIVATE KEY-----.*?"
    r"-----END (?:RSA |EC |OPENSSH )?PRIVATE KEY-----",
    re.DOTALL,
)
[MASK] = re.compile(r"\b(?:sk-proj-|sk-ant-)[A-Za-z0-9_-]{16,}\b")
AWS_KEY = [MASK](r"\bAKIA[0-9A-Z]{16}\b")
BEARER = re.compile(r"(?i)(authorization\s*[:=]\s*bearer\s+)[^\s\"']+")
[MASK]
    r"(?i)((?:x-session-token|session_token)[\"']?\s*[:=]\s*[\"']?)[A-Za-z0-9_-]{20,}"
)
DATABASE_PASSWORD = [MASK](r"(postgresql(?:\+psycopg)?://[^:/\s]+:)[^@/\s]+(@)")
ENV_SECRET = [MASK](
    r"(?im)^(\s*(?:OPENAI_API_KEY|ANTHROPIC_API_KEY|REDIS_PASSWORD)\s*=\s*).+$"
)


def sanitize_text(value: str) -> str:
    value = PRIVATE_KEY.sub("[PRIVATE_KEY_REDACTED]", value)
    value = [MASK].sub("[API_KEY_REDACTED]", value)
    value = AWS_KEY.sub("[AWS_KEY_REDACTED]", value)
    value = BEARER.sub(r"\1[REDACTED]", value)
    value = SESSION_TOKEN.sub(r"\1[SESSION_TOKEN_REDACTED]", value)
    value = DATABASE_PASSWORD.sub(r"\1[DATABASE_PASSWORD_REDACTED]\2", value)
    value = ENV_SECRET.sub(r"\1[REDACTED]", value)
    value = EMAIL.sub("[EMAIL_REDACTED]", value)
    value = CPF.sub("[CPF_REDACTED]", value)
    value = PHONE.sub("[PHONE_REDACTED]", value)
    value = HOME_PATH.sub("$WORKSPACE_HOME", value)
    return PERSON_NAME.sub("[PERSON_REDACTED]", value)


def sanitize(value: Any) -> Any:
    if isinstance(value, str):
        return sanitize_text(value)
    if isinstance(value, list):
        return [sanitize(item) for item in value]
    if isinstance(value, dict):
        return {
            key: "[REDACTED]"
            if key.lower() in {"encrypted_content", "[MASK]", "token", "[MASK]"}
            else sanitize(item)
            for key, item in value.items()
            if key != "internal_chat_message_metadata_passthrough"
        }
    return value


def export_session(source: Path, destination: Path) -> dict[str, int | str]:
    counts = {"messages": 0, "tool_calls": 0, "tool_outputs": 0, "skipped": 0}
    source_hash = hashlib.sha256(source.read_bytes()).hexdigest()
    destination.parent.mkdir(parents=True, exist_ok=True)

    with source.open(encoding="utf-8") as source_file, destination.open(
        "w", encoding="utf-8"
    ) as output_file:
        metadata = {
            "kind": "export_metadata",
            "source": sanitize_text(str(source)),
            "source_sha256_at_export": source_hash,
            "sanitizer": "ai-logs/sanitize_codex_session.py",
            "policy": (
                "Preserva mensagens visíveis de user/assistant, planos, chamadas de ferramentas "
                "e outputs. Exclui developer/system, reasoning, conteúdo criptografado, contagem "
                "de tokens e metadados internos; mascara secrets, [MASK] e PII client-side."
            ),
        }
        output_file.write(json.dumps(metadata, ensure_ascii=False, sort_keys=True) + "\n")

        for line in source_file:
            event = json.loads(line)
            if event.get("type") != "response_item":
                counts["skipped"] += 1
                continue
            payload = event.get("payload", {})
            payload_type = payload.get("type")
            exported: dict[str, Any] | None = None

            if payload_type == "message" and payload.get("role") in {"user", "assistant"}:
                exported = {
                    "timestamp": event.get("timestamp"),
                    "kind": "message",
                    "role": payload.get("role"),
                    "phase": payload.get("phase"),
                    "content": payload.get("content", []),
                }
                counts["messages"] += 1
            elif payload_type in {"custom_tool_call", "function_call"}:
                exported = {
                    "timestamp": event.get("timestamp"),
                    "kind": "tool_call",
                    "tool": payload.get("name"),
                    "call_id": payload.get("call_id"),
                    "input": payload.get("input", payload.get("arguments")),
                }
                counts["tool_calls"] += 1
            elif payload_type in {"custom_tool_call_output", "function_call_output"}:
                exported = {
                    "timestamp": event.get("timestamp"),
                    "kind": "tool_output",
                    "call_id": payload.get("call_id"),
                    "output": payload.get("output"),
                }
                counts["tool_outputs"] += 1
            else:
                counts["skipped"] += 1

            if exported is not None:
                output_file.write(
                    json.dumps(sanitize(exported), ensure_ascii=False, sort_keys=True) + "\n"
                )

    return {**counts, "source_sha256": source_hash}


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("source", type=Path)
    parser.add_argument("destination", type=Path)
    args = parser.parse_args()
    result = export_session(args.source, args.destination)
    print(json.dumps(result, sort_keys=True))


if __name__ == "__main__":
    main()

