    client = QuoteClient(
        "http://quote.test",
        transport=httpx.MockTransport(timeout),
        sleeper=lambda _: None,
        jitter=lambda: 0,
    )
    with pytest.raises(QuoteUnavailable) as error:
        client.quote(DATA)
    assert [attempt.status for attempt in error.value.attempts] == ["timeout"] * 3

