    session_id: Mapped[str] = mapped_column(
        ForeignKey("sessions.id", ondelete="CASCADE"), index=True
    )
    correlation_id: Mapped[str | None] = mapped_column(String(64), nullable=True, index=True)
    span_name: Mapped[str] = mapped_column(String(64), nullable=False)
    status: Mapped[str] = mapped_column(String(24), nullable=False)
    duration_ms: Mapped[int] = mapped_column(Integer, nullable=False)
    attributes: Mapped[dict[str, Any]] = mapped_column(JSON, nullable=False)
    created_at: Mapped[datetime] = mapped_column(DateTime(timezone=True), default=utcnow)

                        "input_tokens": int(usage.input_tokens),
                        "output_tokens": int(usage.output_tokens),
                        "total_tokens": int(usage.input_tokens + usage.output_tokens),
                    }
                    if usage is not None
                    else {}
                )
                return AgentDecision.model_validate(cast(Any, block).input)
        raise ValueError("Anthropic retornou resposta sem decisão estruturada")

    def telemetry_metadata(self) -> dict[str, str | int]:
        return {
            **super().telemetry_metadata(),
            **(_usage_context(self, "anthropic_usage").get() or {}),
        }


def provider_from_settings(settings: Any) -> LLMProvider:
    provider = settings.llm_provider.lower()
    if provider == "fake":
        return FakeProvider()
    if provider == "openai":
        return OpenAIProvider(settings.openai_api_key or "", settings.llm_model)
    if provider in {"agents_sdk", "openai_agents_sdk"}:
        return AgentsSDKProvider(settings.openai_api_key or "", settings.llm_model)
    if provider == "anthropic":
        model = settings.llm_model
        if model == "gpt-5.4-mini":
            model = "claude-sonnet-4-6"
        return AnthropicProvider(settings.anthropic_api_key or "", model)
    raise ValueError(f"LLM_PROVIDER inválido: {settings.llm_provider}")


def decision_for_log(decision: AgentDecision) -> str:
    return json.dumps(decision.model_dump(mode="json"), ensure_ascii=False, sort_keys=True)


def _usage_context(provider: Any, name: str) -> ContextVar[dict[str, int] | None]:
    context = getattr(provider, "_usage", None)
    if context is None:
        context = ContextVar(name, default=None)
        provider._usage = context
    return cast(ContextVar[dict[str, int] | None], context)

from __future__ import annotations

import hashlib
import secrets
import threading
import time
from abc import ABC, abstractmethod
from dataclasses import dataclass
from typing import Any, cast


class CoordinationUnavailable(RuntimeError):
    pass


@dataclass(frozen=True)
class RateLimitDecision:
    allowed: bool
    retry_after: int = 0


class LockLease(ABC):
    @abstractmethod
    def release(self) -> None:
        raise NotImplementedError


class CoordinationBackend(ABC):
    name: str

    @abstractmethod
    def health(self) -> bool:
        raise NotImplementedError

    @abstractmethod
    def rate_limit(self, key: str, *, limit: int, window_seconds: int) -> RateLimitDecision:
        raise NotImplementedError

    @abstractmethod
    def get_idempotency(self, key: str) -> str | None:
        raise NotImplementedError

    @abstractmethod
    def put_idempotency(self, key: str, value: str, *, ttl_seconds: int) -> None:
        raise NotImplementedError

    @abstractmethod
    def acquire_lock(self, key: str, *, ttl_seconds: int) -> LockLease | None:
        raise NotImplementedError

    @abstractmethod
    def circuit_is_open(self, key: str) -> bool:
        raise NotImplementedError

    @abstractmethod
    def circuit_success(self, key: str) -> None:
        raise NotImplementedError

    @abstractmethod
    def circuit_failure(self, key: str, *, threshold: int, open_seconds: int) -> None:
        raise NotImplementedError


@dataclass
class _ExpiringValue:
    value: str
    expires_at: float


class _LocalLease(LockLease):
    def __init__(self, backend: LocalCoordination, key: str, token: str) -> None:
        self.backend = backend
        self.key = key
        self.token = token

    def release(self) -> None:
        self.backend._release_lock(self.key, self.token)


class LocalCoordination(CoordinationBackend):
    """Thread-safe single-process implementation used by default and as rate fallback."""

    name = "local"

    def __init__(self) -> None:
        self._mutex = threading.Lock()
        self._rate: dict[str, tuple[int, float]] = {}
        self._idempotency: dict[str, _ExpiringValue] = {}
        self._locks: dict[str, _ExpiringValue] = {}
        self._circuits: dict[str, tuple[int, float]] = {}

    def health(self) -> bool:
        return True

    def rate_limit(self, key: str, *, limit: int, window_seconds: int) -> RateLimitDecision:
        now = time.monotonic()
        with self._mutex:
            count, expires_at = self._rate.get(key, (0, now + window_seconds))
            if expires_at <= now:
                count, expires_at = 0, now + window_seconds
            if count >= limit:
                return RateLimitDecision(False, max(1, int(expires_at - now + 0.999)))
            self._rate[key] = (count + 1, expires_at)
        return RateLimitDecision(True)

    def get_idempotency(self, key: str) -> str | None:
        now = time.monotonic()
        with self._mutex:
            item = self._idempotency.get(key)
            if item is None:
                return None
            if item.expires_at <= now:
                self._idempotency.pop(key, None)
                return None
            return item.value

    def put_idempotency(self, key: str, value: str, *, ttl_seconds: int) -> None:
        with self._mutex:
            self._idempotency[key] = _ExpiringValue(value, time.monotonic() + ttl_seconds)

    def acquire_lock(self, key: str, *, ttl_seconds: int) -> LockLease | None:
        now = time.monotonic()
        token = [MASK](16)
        with self._mutex:
            current = self._locks.get(key)
            if current is not None and current.expires_at > now:
                return None
            self._locks[key] = _ExpiringValue(token, now + ttl_seconds)
        return _LocalLease(self, key, token)

    def _release_lock(self, key: str, token: str) -> None:
        with self._mutex:
            current = self._locks.get(key)
            if current is not None and current.value == token:
                [MASK](key, None)

    def circuit_is_open(self, key: str) -> bool:
        now = time.monotonic()
        with self._mutex:
            failures, open_until = self._circuits.get(key, (0, 0.0))
            if open_until > now:
                return True
            if open_until:
                self._circuits[key] = (failures, 0.0)
            return False

    def circuit_success(self, key: str) -> None:
        with self._mutex:
            self._circuits.pop(key, None)

    def circuit_failure(self, key: str, *, threshold: int, open_seconds: int) -> None:
        now = time.monotonic()
        with self._mutex:
            failures, open_until = self._circuits.get(key, (0, 0.0))
            if open_until > now:
                return
            failures += 1
            self._circuits[key] = (
                failures,
                now + open_seconds if failures >= threshold else 0.0,
            )


class _RedisLease(LockLease):
    RELEASE_SCRIPT = """
    if redis.call('GET', KEYS[1]) == ARGV[1] then
      return redis.call('DEL', KEYS[1])
    end
    return 0
    """

    def __init__(self, client: Any, key: str, token: str) -> None:
        self.client = client
        self.key = key
        self.token = token

    def release(self) -> None:
        try:
            self.client.eval(self.RELEASE_SCRIPT, 1, self.key, self.token)
        except Exception as exc:
            raise CoordinationUnavailable("redis_lock_release_failed") from exc


class RedisCoordination(CoordinationBackend):
    name = "redis"
    RATE_SCRIPT = """
    local current = redis.call('INCR', KEYS[1])
    if current == 1 then redis.call('EXPIRE', KEYS[1], ARGV[1]) end
    return {current, redis.call('TTL', KEYS[1])}
    """
    CIRCUIT_FAILURE_SCRIPT = """
    local failures = redis.call('INCR', KEYS[1])
    redis.call('EXPIRE', KEYS[1], ARGV[2])
    if failures >= tonumber(ARGV[1]) then
      redis.call('SET', KEYS[2], '1', 'EX', ARGV[2])
      redis.call('DEL', KEYS[1])
    end
    return failures
    """

    def __init__(self, client: Any) -> None:
        self.client = client

    @classmethod
    def from_url(cls, url: str) -> RedisCoordination:
        try:
            from redis import Redis
        except ImportError as exc:
            raise ValueError(
                "COORDINATION_BACKEND=redis requer instalação do extra 'redis'"
            ) from exc
        return cls(
            Redis.from_url(
                url,
                decode_responses=True,
                socket_connect_timeout=0.5,
                socket_timeout=0.5,
            )
        )

    def health(self) -> bool:
        try:
            return bool(self.client.ping())
        except Exception:
            return False

    def rate_limit(self, key: str, *, limit: int, window_seconds: int) -> RateLimitDecision:
        try:
            result = cast(list[int], self.client.eval(self.RATE_SCRIPT, 1, key, window_seconds))
            count, ttl = int(result[0]), max(1, int(result[1]))
            return RateLimitDecision(count <= limit, ttl if count > limit else 0)
        except Exception as exc:
            raise CoordinationUnavailable("redis_rate_limit_failed") from exc

    def get_idempotency(self, key: str) -> str | None:
        try:
            value = self.client.get(key)
            return str(value) if value is not None else None
        except Exception as exc:
            raise CoordinationUnavailable("redis_idempotency_read_failed") from exc

    def put_idempotency(self, key: str, value: str, *, ttl_seconds: int) -> None:
        try:
            self.client.set(key, value, ex=ttl_seconds)
        except Exception as exc:
            raise CoordinationUnavailable("redis_idempotency_write_failed") from exc

    def acquire_lock(self, key: str, *, ttl_seconds: int) -> LockLease | None:
        token = [MASK](16)
        try:
            acquired = self.client.set(key, token, nx=True, ex=ttl_seconds)
            return _RedisLease(self.client, key, token) if acquired else None
        except Exception as exc:
            raise CoordinationUnavailable("redis_lock_failed") from exc

    def circuit_is_open(self, key: str) -> bool:
        try:
            return bool(self.client.exists(key))
        except Exception as exc:
            raise CoordinationUnavailable("redis_circuit_read_failed") from exc

    def circuit_success(self, key: str) -> None:
        try:
            self.client.delete(f"{key}:failures", key)
        except Exception as exc:
            raise CoordinationUnavailable("redis_circuit_reset_failed") from exc

    def circuit_failure(self, key: str, *, threshold: int, open_seconds: int) -> None:
        try:
            self.client.eval(
                self.CIRCUIT_FAILURE_SCRIPT,
                2,
                f"{key}:failures",
                key,
                threshold,
                open_seconds,
            )
        except Exception as exc:
            raise CoordinationUnavailable("redis_circuit_write_failed") from exc


def opaque_key(namespace: str, *parts: str) -> str:
    digest = hashlib.sha256("\x1f".join(parts).encode()).hexdigest()
    return f"autoseguro:{namespace}:{digest}"


def coordination_from_config(backend: str, redis_url: str) -> CoordinationBackend:
    if backend == "local":
        return LocalCoordination()
    if backend == "redis":
        return RedisCoordination.from_url(redis_url)
    raise ValueError("COORDINATION_BACKEND deve ser 'local' ou 'redis'")
from __future__ import annotations

import logging
import random
import time
import uuid
from collections.abc import Callable
from typing import Any

import httpx

from .coordination import CoordinationBackend, CoordinationUnavailable, opaque_key
from .domain import ExtractedData, QuoteAttempt, QuoteResult

logger = logging.getLogger(__name__)


class QuoteError(Exception):
    def __init__(self, message: str, quote_id: str, attempts: list[QuoteAttempt]) -> None:
        super().__init__(message)
        self.quote_id = quote_id
        self.attempts = attempts


class QuoteUnavailable(QuoteError):
    pass


class QuoteRejected(QuoteError):
    def __init__(self, reason: str, quote_id: str, attempts: list[QuoteAttempt]) -> None:
        super().__init__(reason, quote_id, attempts)
        self.reason = reason


class QuoteInvalid(QuoteError):
    pass


class QuoteClient:
    RETRYABLE = {500, 502, 503}

    def __init__(
        self,
        base_url: str,
        *,
        timeout_seconds: float = 3.0,
        max_attempts: int = 3,
        backoff_seconds: float = 0.25,
        transport: httpx.BaseTransport | None = None,
        sleeper: Callable[[float], None] = time.sleep,
        jitter: Callable[[], float] = random.random,
        coordination: CoordinationBackend | None = None,
        circuit_breaker_threshold: int = 3,
        circuit_breaker_open_seconds: int = 30,
    ) -> None:
        self.base_url = base_url.rstrip("/")
        self.timeout_seconds = timeout_seconds
        self.max_attempts = max_attempts
        self.backoff_seconds = backoff_seconds
        self.transport = transport
        self.sleeper = sleeper
        self.jitter = jitter
        self.coordination = coordination
        self.circuit_breaker_threshold = circuit_breaker_threshold
        self.circuit_breaker_open_seconds = circuit_breaker_open_seconds
        self.circuit_key = [MASK]("circuit", self.base_url, "quote")

    def health(self) -> bool:
        try:
            with httpx.Client(transport=self.transport, timeout=self.timeout_seconds) as client:
                return client.get(f"{self.base_url}/health").status_code == 200
        except httpx.HTTPError:
            return False

    def quote(self, data: ExtractedData) -> QuoteResult:
        quote_id = str(uuid.uuid4())
        attempts: list[QuoteAttempt] = []
        if self._circuit_is_open():
            attempts.append(
                QuoteAttempt(
                    attempt_no=0,
                    status="circuit_open",
                    duration_ms=0,
                    error_code="circuit_open",
                )
            )
            raise QuoteUnavailable("Circuit breaker aberto.", quote_id, attempts)
        payload: dict[str, Any] = {
            "plano_id": data.plan_id,
            "idade": data.age,
            "veiculo_ano": data.vehicle_year,
            "cep": data.cep_prefix,
            "data_inicio": data.start_date.isoformat() if data.start_date else None,
        }

        with httpx.Client(transport=self.transport, timeout=self.timeout_seconds) as client:
            for attempt_no in range(1, self.max_attempts + 1):
                started = time.monotonic()
                try:
                    response = client.post(f"{self.base_url}/quote", json=payload)
                    duration_ms = round((time.monotonic() - started) * 1000)
                    body = _safe_json(response)
                    if response.status_code == 200:
                        attempts.append(
                            QuoteAttempt(
                                attempt_no=attempt_no,
                                status="success",
                                http_status=200,
                                duration_ms=duration_ms,
                                response_payload=body,
                            )
                        )
                        self._circuit_success()
                        return QuoteResult(quote_id=quote_id, payload=body, attempts=attempts)
                    if response.status_code == 422:
                        attempts.append(
                            QuoteAttempt(
                                attempt_no=attempt_no,
                                status="rejected",
                                http_status=422,
                                duration_ms=duration_ms,
                                error_code="cotacao_recusada",
                            )
                        )
                        raise QuoteRejected(
                            str(body.get("motivo", "Cotação recusada.")), quote_id, attempts
                        )
                    if response.status_code not in self.RETRYABLE:
                        attempts.append(
                            QuoteAttempt(
                                attempt_no=attempt_no,
                                status="invalid",
                                http_status=response.status_code,
                                duration_ms=duration_ms,
                                error_code=str(body.get("error", "payload_invalido")),
                            )
                        )
                        raise QuoteInvalid("Quote-service recusou o payload.", quote_id, attempts)
                    attempts.append(
                        QuoteAttempt(
                            attempt_no=attempt_no,
                            status="retryable_error",
                            http_status=response.status_code,
                            duration_ms=duration_ms,
                            error_code=str(body.get("error", "upstream_unavailable")),
                        )
                    )
                except QuoteError:
                    raise
                except httpx.TimeoutException:
                    attempts.append(
                        QuoteAttempt(
                            attempt_no=attempt_no,
                            status="timeout",
                            duration_ms=round((time.monotonic() - started) * 1000),
                            error_code="timeout",
                        )
                    )
                except httpx.HTTPError:
                    attempts.append(
                        QuoteAttempt(
                            attempt_no=attempt_no,
                            status="transport_error",
                            duration_ms=round((time.monotonic() - started) * 1000),
                            error_code="transport_error",
                        )
                    )

                if attempt_no < self.max_attempts:
                    delay = self.backoff_seconds * (2 ** (attempt_no - 1))
                    self.sleeper(delay + self.jitter() * self.backoff_seconds)

        self._circuit_failure()
        raise QuoteUnavailable("Serviço de cotação indisponível.", quote_id, attempts)

    def _circuit_is_open(self) -> bool:
        if self.coordination is None:
            return False
        try:
            return self.coordination.circuit_is_open(self.circuit_key)
        except CoordinationUnavailable:
            logger.warning("circuit_breaker_degraded", extra={"operation": "read"})
            return False

    def _circuit_success(self) -> None:
        if self.coordination is None:
            return
        try:
            self.coordination.circuit_success(self.circuit_key)
        except CoordinationUnavailable:
            logger.warning("circuit_breaker_degraded", extra={"operation": "reset"})

    def _circuit_failure(self) -> None:
        if self.coordination is None:
            return
        try:
            self.coordination.circuit_failure(
                self.circuit_key,
                threshold=self.circuit_breaker_threshold,
                open_seconds=self.circuit_breaker_open_seconds,
            )
        except CoordinationUnavailable:
            logger.warning("circuit_breaker_degraded", extra={"operation": "write"})


def _safe_json(response: httpx.Response) -> dict[str, Any]:
    try:
        parsed = response.json()
        return parsed if isinstance(parsed, dict) else {"value": parsed}
    except ValueError:
        return {"error": "invalid_json"}
from __future__ import annotations

import logging
from dataclasses import dataclass
from enum import StrEnum
from pathlib import Path
from typing import Any

from .telemetry import SafeTelemetry

logger = logging.getLogger(__name__)


class PolicyAction(StrEnum):
    CALL_LLM = "CallLLM"
    CALL_QUOTE = "CallQuote"
    PERSIST_AUDIT = "PersistAudit"
    COMPLETE_SESSION = "CompleteSession"
    HANDOFF_SESSION = "HandoffSession"


@dataclass(frozen=True)
class PolicyDecision:
    allowed: bool
    engine_available: bool
    reasons: tuple[str, ...] = ()
    error_category: str | None = None


class PolicyEngine:
    name = "unavailable"

    def evaluate(
        self, action: PolicyAction, session_id: str, context: dict[str, Any]
    ) -> PolicyDecision:
        del action, session_id, context
        return PolicyDecision(
            allowed=False,
            engine_available=False,
            error_category="engine_unavailable",
        )


class CedarPolicyEngine(PolicyEngine):
    name = "cedarpy"

    def __init__(self, policy_path: Path, schema_path: Path) -> None:
        from cedarpy import PolicySet, Schema, validate_policies

        policy_text = policy_path.read_text(encoding="utf-8")
        schema_text = schema_path.read_text(encoding="utf-8")
        validation = validate_policies(policy_text, schema_text)
        if not validation.validation_passed:
            errors = "; ".join(str(error) for error in validation.errors)
            raise ValueError(f"Cedar policy validation failed: {errors}")
        self.policy_set = PolicySet.from_str(policy_text)
        self.schema = Schema.from_str(schema_text)

    def evaluate(
        self, action: PolicyAction, session_id: str, context: dict[str, Any]
    ) -> PolicyDecision:
        try:
            from cedarpy import Decision, is_authorized

            entity = {"type": "AutoSeguro::Session", "id": session_id}
            request = {
                "principal": entity,
                "action": {"type": "AutoSeguro::Action", "id": action.value},
                "resource": entity,
                "context": context,
            }
            entities = [{"uid": entity, "attrs": {}, "parents": []}]
            result = is_authorized(
                request,
                self.policy_set,
                entities,
                schema=self.schema,
            )
            return PolicyDecision(
                allowed=result.decision is Decision.Allow,
                engine_available=True,
                reasons=tuple(result.diagnostics.reasons),
                error_category=("evaluation_error" if result.diagnostics.errors else None),
            )
        except Exception as exc:
            logger.warning("cedar_evaluation_failed", extra={"error_type": type(exc).__name__})
            return PolicyDecision(
                allowed=False,
                engine_available=False,
                error_category=type(exc).__name__,
            )


class PolicyController:
    def __init__(
        self,
        engine: PolicyEngine,
        *,
        mode: str,
        enforce_actions: set[PolicyAction],
        telemetry: SafeTelemetry,
    ) -> None:
        if mode not in {"off", "shadow", "enforce"}:
            raise ValueError("POLICY_MODE deve ser 'off', 'shadow' ou 'enforce'")
        self.engine = engine
        self.mode = mode
        self.enforce_actions = enforce_actions
        self.telemetry = telemetry

    def check(
        self, action: PolicyAction, session_id: str, context: dict[str, Any]
    ) -> PolicyDecision:
        if self.mode == "off":
            return PolicyDecision(allowed=True, engine_available=False, reasons=("disabled",))
        decision = self.engine.evaluate(action, session_id, context)
        with self.telemetry.span(
            "cedar_policy_decision",
            {
                "session_id": session_id,
                "policy_action": action.value,
                "policy_mode": self.mode,
                "policy_engine": self.engine.name,
                "allowed": decision.allowed,
                "engine_available": decision.engine_available,
                "error_category": decision.error_category,
            },
        ):
            pass
        return decision

    def blocks(self, action: PolicyAction, decision: PolicyDecision) -> bool:
        return self.mode == "enforce" and action in self.enforce_actions and not decision.allowed


def policy_from_config(
    *,
    mode: str,
    policy_path: str,
    schema_path: str,
    enforce_actions: str,
    telemetry: SafeTelemetry,
) -> PolicyController:
    engine: PolicyEngine
    try:
        engine = CedarPolicyEngine(Path(policy_path), Path(schema_path))
    except Exception as exc:
        logger.warning("cedar_initialization_failed", extra={"error_type": type(exc).__name__})
        engine = PolicyEngine()
    parsed_actions: set[PolicyAction] = set()
    for item in enforce_actions.split(","):
        if item.strip():
            parsed_actions.add(PolicyAction(item.strip()))
    return PolicyController(
        engine,
        mode=mode,
        enforce_actions=parsed_actions,
        telemetry=telemetry,
    )
// Default deny: Cedar denies when no permit policy matches.

permit (
  principal is AutoSeguro::Session,
  action == AutoSeguro::Action::"CallLLM",
  resource is AutoSeguro::Session
)
when {
  resource == principal &&
  context.sessionState != "completed" &&
  context.sessionState != "handoff" &&
  context.sanitized &&
  ["openai", "anthropic", "fake"].contains(context.destination)
};

permit (
  principal is AutoSeguro::Session,
  action == AutoSeguro::Action::"CallQuote",
  resource is AutoSeguro::Session
)
when {
  resource == principal &&
  context.sessionState == "confirmation" &&
  context.dataComplete &&
  context.confirmed &&
  context.sanitized &&
  context.destination == "quote-service"
};

permit (
  principal is AutoSeguro::Session,
  action == AutoSeguro::Action::"PersistAudit",
  resource is AutoSeguro::Session
)
when { resource == principal && context.sanitized };

permit (
  principal is AutoSeguro::Session,
  action == AutoSeguro::Action::"CompleteSession",
  resource is AutoSeguro::Session
)
when {
  resource == principal &&
  context.sessionState == "quote_presented" &&
  context.quoteSucceeded
};

permit (
  principal is AutoSeguro::Session,
  action == AutoSeguro::Action::"HandoffSession",
  resource is AutoSeguro::Session
)
when { resource == principal && context.reasonPresent };
namespace AutoSeguro {
  entity Session;

  action CallLLM appliesTo {
    principal: [Session],
    resource: [Session],
    context: {
      sessionState: String,
      sanitized: Bool,
      destination: String
    }
  };

  action CallQuote appliesTo {
    principal: [Session],
    resource: [Session],
    context: {
      sessionState: String,
      dataComplete: Bool,
      confirmed: Bool,
      sanitized: Bool,
      destination: String
    }
  };

  action PersistAudit appliesTo {
    principal: [Session],
    resource: [Session],
    context: { sanitized: Bool }
