        self.repository.add_quote_attempts(session_id, quote_id, attempts)


def _message_view(record: Any) -> MessageView:
    return MessageView(
        id=record.id,
        role=record.role,
        message_type=record.message_type,
        content=record.content,
        created_at=record.created_at,
    )


def _missing_fields(data: ExtractedData) -> list[str]:
    fields = [
        ("modelo do veículo", data.vehicle_model),
        ("ano do veículo", data.vehicle_year),
        ("idade", data.age),
        ("CEP", data.cep_prefix),
        ("plano", data.plan_id),
    ]
    return [name for name, value in fields if value is None]


def _question_for(field: str) -> str:
    questions = {
        "modelo do veículo": "Qual é o modelo do veículo?",
        "ano do veículo": "Qual é o ano do veículo?",
        "idade": "Qual é a sua idade?",
        "CEP": "Qual é o CEP onde o veículo pernoita? Usarei somente os dois primeiros dígitos.",
        "plano": (
            "Qual plano você quer cotar: Essencial, Completo ou Premium? "
            "Essencial cobre colisão, roubo e furto; Completo inclui terceiros e vidros; "
            "Premium acrescenta carro reserva e assistência 24h."
        ),
    }
    return questions[field]


def _confirmation_message(data: ExtractedData) -> str:
    return (
        f"Confirma a cotação do plano {data.plan_id} para {data.vehicle_model} "
        f"{data.vehicle_year}, condutor de {data.age} anos e região de CEP "
        f"{data.cep_prefix}***-***?"
    )


def _format_quote(payload: dict[str, Any]) -> str:
    price = float(payload["premio_mensal"])
    franchise = float(payload["franquia"])
    coverages = ", ".join(str(item).replace("_", " ") for item in payload["coberturas"])
    message = (
        f"Cotação oficial: plano {payload['plano_nome']}, mensalidade de R$ {_brl(price)}, "
        f"franquia de R$ {_brl(franchise)}. Coberturas: {coverages}. "
        f"Roubo e furto têm carência de {payload['carencia']['dias']} dias."
    )
    pro_rata = payload.get("primeiro_pagamento_pro_rata")
    if pro_rata:
        first_payment = float(pro_rata["valor_primeiro_pagamento"])
        message += f" Primeiro pagamento proporcional: R$ {_brl(first_payment)}."
    return message + " Deseja registrar interesse nesta proposta?"


def _brl(value: float) -> str:
    return f"{value:,.2f}".replace(",", "_").replace(".", ",").replace("_", ".")
from __future__ import annotations

import logging
import random
import time
import uuid
from collections.abc import Callable
from typing import Any

import httpx
from pydantic import ValidationError

from .coordination import CoordinationBackend, CoordinationUnavailable, opaque_key
from .domain import ExtractedData, QuoteAttempt, QuotePayload, QuoteResult

logger = logging.getLogger(__name__)


class QuoteError(Exception):
    def __init__(self, message: str, quote_id: str, attempts: list[QuoteAttempt]) -> None:
        super().__init__(message)
        self.quote_id = quote_id
        self.attempts = attempts


class QuoteUnavailable(QuoteError):
    pass


class QuoteRejected(QuoteError):
    def __init__(self, reason: str, quote_id: str, attempts: list[QuoteAttempt]) -> None:
        super().__init__(reason, quote_id, attempts)
        self.reason = reason


class QuoteInvalid(QuoteError):
    pass


class QuoteClient:
    RETRYABLE = {500, 502, 503}

    def __init__(
        self,
        base_url: str,
        *,
        timeout_seconds: float = 3.0,
        max_attempts: int = 3,
        backoff_seconds: float = 0.25,
        transport: httpx.BaseTransport | None = None,
        sleeper: Callable[[float], None] = time.sleep,
        jitter: Callable[[], float] = random.random,
        coordination: CoordinationBackend | None = None,
        circuit_breaker_threshold: int = 3,
        circuit_breaker_open_seconds: int = 30,
    ) -> None:
        self.base_url = base_url.rstrip("/")
        self.timeout_seconds = timeout_seconds
        self.max_attempts = max_attempts
        self.backoff_seconds = backoff_seconds
        self.transport = transport
        self.sleeper = sleeper
        self.jitter = jitter
        self.coordination = coordination
        self.circuit_breaker_threshold = circuit_breaker_threshold
        self.circuit_breaker_open_seconds = circuit_breaker_open_seconds
        self.circuit_key = [MASK]("circuit", self.base_url, "quote")

    def health(self) -> bool:
        try:
            with httpx.Client(transport=self.transport, timeout=self.timeout_seconds) as client:
                return client.get(f"{self.base_url}/health").status_code == 200
        except httpx.HTTPError:
            return False

    def quote(self, data: ExtractedData) -> QuoteResult:
        quote_id = str(uuid.uuid4())
        attempts: list[QuoteAttempt] = []
        if self._circuit_is_open():
            attempts.append(
                QuoteAttempt(
                    attempt_no=0,
                    status="circuit_open",
                    duration_ms=0,
                    error_code="circuit_open",
                )
            )
            raise QuoteUnavailable("Circuit breaker aberto.", quote_id, attempts)
        payload: dict[str, Any] = {
            "plano_id": data.plan_id,
            "idade": data.age,
            "veiculo_ano": data.vehicle_year,
            "cep": data.cep_prefix,
            "data_inicio": data.start_date.isoformat() if data.start_date else None,
        }

        with httpx.Client(transport=self.transport, timeout=self.timeout_seconds) as client:
            for attempt_no in range(1, self.max_attempts + 1):
                started = time.monotonic()
                try:
                    response = client.post(f"{self.base_url}/quote", json=payload)
                    duration_ms = round((time.monotonic() - started) * 1000)
                    body = _safe_json(response)
                    if response.status_code == 200:
                        try:
                            body = QuotePayload.model_validate(body).model_dump(mode="json")
                        except ValidationError as exc:
                            attempts.append(
                                QuoteAttempt(
                                    attempt_no=attempt_no,
                                    status="invalid",
                                    http_status=200,
                                    duration_ms=duration_ms,
                                    error_code="invalid_response_schema",
                                )
                            )
                            raise QuoteInvalid(
                                "Quote-service retornou resposta inválida.", quote_id, attempts
                            ) from exc
                        attempts.append(
                            QuoteAttempt(
                                attempt_no=attempt_no,
                                status="success",
                                http_status=200,
                                duration_ms=duration_ms,
                                response_payload=body,
                            )
                        )
                        self._circuit_success()
                        return QuoteResult(quote_id=quote_id, payload=body, attempts=attempts)
                    if response.status_code == 422:
                        attempts.append(
                            QuoteAttempt(
                                attempt_no=attempt_no,
                                status="rejected",
                                http_status=422,
                                duration_ms=duration_ms,
                                error_code="cotacao_recusada",
                            )
                        )
                        raise QuoteRejected(
                            str(body.get("motivo", "Cotação recusada.")), quote_id, attempts
                        )
                    if response.status_code not in self.RETRYABLE:
                        attempts.append(
                            QuoteAttempt(
                                attempt_no=attempt_no,
                                status="invalid",
                                http_status=response.status_code,
                                duration_ms=duration_ms,
                                error_code=str(body.get("error", "payload_invalido")),
                            )
                        )
                        raise QuoteInvalid("Quote-service recusou o payload.", quote_id, attempts)
                    attempts.append(
                        QuoteAttempt(
                            attempt_no=attempt_no,
                            status="retryable_error",
                            http_status=response.status_code,
                            duration_ms=duration_ms,
                            error_code=str(body.get("error", "upstream_unavailable")),
                        )
                    )
                except QuoteError:
                    raise
                except httpx.TimeoutException:
                    attempts.append(
                        QuoteAttempt(
                            attempt_no=attempt_no,
                            status="timeout",
                            duration_ms=round((time.monotonic() - started) * 1000),
                            error_code="timeout",
                        )
                    )
                except httpx.HTTPError:
                    attempts.append(
                        QuoteAttempt(
                            attempt_no=attempt_no,
                            status="transport_error",
                            duration_ms=round((time.monotonic() - started) * 1000),
                            error_code="transport_error",
                        )
                    )

                if attempt_no < self.max_attempts:
                    delay = self.backoff_seconds * (2 ** (attempt_no - 1))
                    self.sleeper(delay + self.jitter() * self.backoff_seconds)

        self._circuit_failure()
        raise QuoteUnavailable("Serviço de cotação indisponível.", quote_id, attempts)

    def _circuit_is_open(self) -> bool:
        if self.coordination is None:
            return False
        try:
            return self.coordination.circuit_is_open(self.circuit_key)
        except CoordinationUnavailable:
            logger.warning("circuit_breaker_degraded", extra={"operation": "read"})
            return False

    def _circuit_success(self) -> None:
        if self.coordination is None:
            return
        try:
            self.coordination.circuit_success(self.circuit_key)
        except CoordinationUnavailable:
            logger.warning("circuit_breaker_degraded", extra={"operation": "reset"})

    def _circuit_failure(self) -> None:
        if self.coordination is None:
            return
        try:
            self.coordination.circuit_failure(
                self.circuit_key,
                threshold=self.circuit_breaker_threshold,
                open_seconds=self.circuit_breaker_open_seconds,
            )
        except CoordinationUnavailable:
            logger.warning("circuit_breaker_degraded", extra={"operation": "write"})


def _safe_json(response: httpx.Response) -> dict[str, Any]:
    try:
        parsed = response.json()
        return parsed if isinstance(parsed, dict) else {"value": parsed}
    except ValueError:
        return {"error": "invalid_json"}
from __future__ import annotations

import uuid
from collections.abc import Iterator
from contextlib import contextmanager
from typing import Any

from sqlalchemy import Engine, create_engine, select, text
from sqlalchemy.orm import Session, selectinload, sessionmaker

from .domain import ExtractedData, QuoteAttempt, SessionState, SessionStatus
from .errors import SessionNotFoundError
from .models import (
    Base,
    HandoffRecord,
    MessageRecord,
    QuoteAttemptRecord,
    SessionRecord,
    TraceEventRecord,
    TransitionRecord,
)
from .security import token_matches


def create_db_engine(
    database_url: str,
    *,
    pool_size: int = 5,
    max_overflow: int = 5,
    pool_timeout: float = 3.0,
    pool_recycle: int = 1800,
) -> Engine:
    options: dict[str, Any] = {"pool_pre_ping": True}
    if not database_url.startswith("sqlite"):
        options.update(
            pool_size=pool_size,
            max_overflow=max_overflow,
            pool_timeout=pool_timeout,
            pool_recycle=pool_recycle,
        )
    return create_engine(database_url, **options)


class Repository:
    def __init__(self, engine: Engine) -> None:
        self.engine = engine
        self.session_factory = sessionmaker(bind=engine, expire_on_commit=False)

    def create_schema(self) -> None:
        Base.metadata.create_all(self.engine)

    def ping(self) -> bool:
        try:
            with self.engine.connect() as connection:
                connection.execute(text("SELECT 1"))
            return True
        except Exception:
            return False

    @contextmanager
    def transaction(self) -> Iterator[Session]:
        with self.session_factory() as db, db.begin():
            yield db

    def create_session(self, session_token_hash: str) -> SessionRecord:
        record = SessionRecord(
            id=str(uuid.uuid4()),
            status=SessionStatus.ACTIVE.value,
            state=SessionState.QUALIFICATION.value,
            collected=ExtractedData().model_dump(mode="json"),
            session_token_hash=[MASK],
        )
        with self.transaction() as db:
            db.add(record)
        return self.get_session(record.id)

    def get_session(self, session_id: str) -> SessionRecord:
        statement = (
            select(SessionRecord)
            .where(SessionRecord.id == session_id)
            .options(
                selectinload(SessionRecord.messages),
                selectinload(SessionRecord.quote_attempts),
                selectinload(SessionRecord.transitions),
                selectinload(SessionRecord.handoff),
            )
        )
        with self.session_factory() as db:
            record = db.scalar(statement)
            if record is None:
                raise SessionNotFoundError()
            db.expunge(record)
            return record

    def authorize_session(self, session_id: str, token: str) -> None:
        with self.session_factory() as db:
            token_hash = db.scalar(
                select(SessionRecord.session_token_hash).where(SessionRecord.id == session_id)
            )
        if not token_matches(token, token_hash):
            raise SessionNotFoundError()

    def add_message(
        self, session_id: str, role: str, message_type: str, content: str
    ) -> MessageRecord:
        record = MessageRecord(
            id=str(uuid.uuid4()),
            session_id=session_id,
            role=role,
            message_type=message_type,
            content=content,
        )
        with self.transaction() as db:
            db.add(record)
        return record

    def update_session(
        self,
        session_id: str,
        *,
        state: SessionState | None = None,
        status: SessionStatus | None = None,
        collected: ExtractedData | None = None,
        clarification_count: int | None = None,
        quote_payload: dict[str, Any] | None = None,
        event: str | None = None,
    ) -> None:
        with self.transaction() as db:
            record = db.get(SessionRecord, session_id)
            if record is None:
                raise SessionNotFoundError()
            old_state = record.state
            if state is not None:
                record.state = state.value
            if status is not None:
                record.status = status.value
            if collected is not None:
                record.collected = collected.model_dump(mode="json")
            if clarification_count is not None:
                record.clarification_count = clarification_count
            if quote_payload is not None:
                record.quote_payload = quote_payload
            if state is not None and state.value != old_state:
                db.add(
                    TransitionRecord(
                        session_id=session_id,
                        from_state=old_state,
                        to_state=state.value,
                        event=event or "state_changed",
                    )
                )

    def add_quote_attempts(
        self, session_id: str, quote_id: str, attempts: list[QuoteAttempt]
    ) -> None:
        with self.transaction() as db:
            for attempt in attempts:
                db.add(
                    QuoteAttemptRecord(
                        session_id=session_id,
                        quote_id=quote_id,
                        **attempt.model_dump(),
                    )
                )

    def add_handoff(self, session_id: str, reason: str, summary: dict[str, Any]) -> None:
        with self.transaction() as db:
            db.add(HandoffRecord(session_id=session_id, reason=reason, summary=summary))

    def add_trace_event(
        self,
        session_id: str,
        *,
        correlation_id: str | None,
        span_name: str,
        status: str,
        duration_ms: int,
        attributes: dict[str, Any],
    ) -> None:
        with self.transaction() as db:
            db.add(
                TraceEventRecord(
                    session_id=session_id,
                    correlation_id=correlation_id,
                    span_name=span_name,
                    status=status,
                    duration_ms=duration_ms,
                    attributes=attributes,
                )
            )

    def list_trace_events(self, session_id: str) -> list[TraceEventRecord]:
        with self.session_factory() as db:
            records = list(
                db.scalars(
                    select(TraceEventRecord)
                    .where(TraceEventRecord.session_id == session_id)
                    .order_by(TraceEventRecord.id)
                )
            )
            for record in records:
                db.expunge(record)
            return records

